// BatchUpdateAvailabilityWithBody Update availability across many properties
//
// Applies ONE settings object across up to 500 properties and pushes the result to every connected channel.
//
// Ownership is checked before anything is written: a batch containing a property from another workspace is refused as a whole and names the offending ids, rather than being partially applied.
//
// Per-property *different* values are separate calls — presenting them as one request would be a false claim about atomicity.
//
// Takes any type of body and a specified content type.
//
// Corresponds with PATCH /v1/availability/batch (the `BatchUpdateAvailability` operationId).
func (c *Client) BatchUpdateAvailabilityWithBody(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewBatchUpdateAvailabilityRequestWithBody(c.Server, contentType, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

